<script>
const adjustType=document.getElementById('adjustType'),adjustScope=document.getElementById('adjustScope'),adjustCylinderType=document.getElementById('adjustCylinderType'),sourceCylinder=document.getElementById('sourceCylinder'),sourceCylinderWrap=document.getElementById('sourceCylinderWrap'),quantity=document.getElementById('adjustQuantity'),quantityLabel=document.getElementById('quantityLabel'),actualGas=document.getElementById('adjustActualGas'),actualGasWrap=document.getElementById('actualGasWrap'),preview=document.getElementById('stockPreview'),help=document.getElementById('adjustHelp');
function refreshAdjustment(){const type=adjustType.value,increase=document.querySelector('input[name="direction"]:checked')?.value==='in';if(type==='gas_kg')adjustScope.value='specific';Array.from(adjustScope.options).forEach(o=>o.disabled=type==='gas_kg'&&o.value!=='specific');const specific=adjustScope.value==='specific',filled=type==='filled_cylinder';sourceCylinderWrap.style.display=specific?'block':'none';sourceCylinder.disabled=!specific;sourceCylinder.required=specific;adjustCylinderType.required=true;Array.from(sourceCylinder.options).forEach(o=>{if(!o.value)return;const match=adjustCylinderType.value!==''&&o.dataset.type===adjustCylinderType.value,status=o.dataset.status;let valid=match;if(type==='gas_kg')valid=match&&(status==='filled'||status==='empty');else if(type==='filled_cylinder')valid=match&&(increase?status==='empty':status==='filled');else valid=match&&status==='empty'&&!increase;o.hidden=!valid;if(!valid&&o.selected)sourceCylinder.value='';});quantity.max=specific&&type!=='gas_kg'?'1':'';quantity.step='.01';quantityLabel.textContent=type==='gas_kg'?'Gas Quantity (KG)':'Cylinder Quantity';actualGasWrap.style.display=filled&&increase?'block':'none';actualGas.disabled=!(filled&&increase);actualGas.required=filled&&increase;help.textContent=specific?(type==='gas_kg'?'Gas changes the actual weight on the selected physical cylinder. When gas reaches zero, the cylinder becomes empty.':'Only the selected physical cylinder is changed. Its before/after state is recorded in history.'):(type==='filled_cylinder'&&increase?'Creates new filled physical cylinders with the entered gas weight per cylinder.':'Adjusts physical cylinder quantity by the selected cylinder type.');updatePreview();}
function updatePreview(){const o=sourceCylinder.options[sourceCylinder.selectedIndex],t=adjustCylinderType.options[adjustCylinderType.selectedIndex],type=adjustType.value,specific=adjustScope.value==='specific',dir=document.querySelector('input[name="direction"]:checked')?.value==='in',q=Number(quantity.value||0);if(specific&&o&&o.value){const gas=Number(o.dataset.gas||0),cap=Number(o.dataset.capacity||0);preview.innerHTML='<strong>'+o.text.split(' — ')[0]+'</strong> · Current gas: <strong>'+gas.toFixed(2)+' KG</strong> · Capacity: '+cap.toFixed(2)+' KG<br>Expected: '+(dir?'+':'−')+q.toFixed(2)+(type==='gas_kg'?' KG':' unit(s)');}else if(t&&t.value){preview.innerHTML='<strong>'+t.text+'</strong><br>Current stock will be revalidated when you post the adjustment. Exact before/after values will be recorded in history.';}else preview.textContent='Select the cylinder type or physical cylinder to see the current stock and expected change.';}
[adjustType,adjustScope,adjustCylinderType,sourceCylinder,quantity].forEach(e=>e?.addEventListener('change',refreshAdjustment));quantity?.addEventListener('input',updatePreview);document.querySelectorAll('input[name="direction"]').forEach(e=>e.addEventListener('change',refreshAdjustment));refreshAdjustment();
document.querySelectorAll('[data-adjust-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-adjust-tab]').forEach(b=>b.classList.toggle('active',b===btn));document.querySelectorAll('[data-adjust-panel]').forEach(p=>p.classList.toggle('d-none',p.dataset.adjustPanel!==btn.dataset.adjustTab));}));
document.querySelectorAll('[data-history-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-history-tab]').forEach(b=>b.classList.toggle('active',b===btn));document.querySelectorAll('[data-history-panel]').forEach(p=>p.classList.toggle('d-none',p.dataset.historyPanel!==btn.dataset.historyTab));}));
</script>
